// @ts-check
// 全站静态配置（头像 / 赞赏码 / 默认身份）
const CONFIG = {
  nameZh: "维托里奥 崔",
  nameEn: "Vittorio Cui",
  email: "velosovittoria545@gmail.com",
  adminUsername: "admin",
  adminPassword: "",
  avatarBase64: "",
  rewardQrBase64: ""
};

/**
 * 内置赞赏码的原始字节。
 *
 * 这张图原先是以 base64 直接内联在 /articles 页面里的（116KB，占整页一半），
 * 现在改由 GET /assets/reward-qr 提供：浏览器只下载一次，之后靠一年强缓存命中。
 * 这里做懒解码 + 缓存，避免每个请求都 atob 一遍 45KB 的 base64。
 */
let _rewardQrBytes = null;
function getRewardQrBytes() {
  if (_rewardQrBytes) return _rewardQrBytes;
  const bin = atob(CONFIG.rewardQrBase64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  _rewardQrBytes = bytes;
  return _rewardQrBytes;
}

export { CONFIG, getRewardQrBytes };
